package com.procurement.goodsreceipt.entity;import com.procurement.product.entity.Product;import com.procurement.purchaseorder.entity.PurchaseOrderLine;import com.procurement.warehouse.entity.Warehouse;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;@Entity@Table(name="goods_receipt_lines")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class GoodsReceiptLine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="grn_line_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="grn_id",nullable=false)private GoodsReceiptNote goodsReceiptNote;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_line_id",nullable=false)private PurchaseOrderLine purchaseOrderLine;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Column(name="ordered_quantity",nullable=false,precision=15,scale=3)private BigDecimal orderedQuantity;@Column(name="received_quantity",nullable=false,precision=15,scale=3)private BigDecimal receivedQuantity;@Column(name="accepted_quantity",nullable=false,precision=15,scale=3)private BigDecimal acceptedQuantity;@Column(name="rejected_quantity",nullable=false,precision=15,scale=3)private BigDecimal rejectedQuantity;@Column(name="damaged_quantity",nullable=false,precision=15,scale=3)private BigDecimal damagedQuantity;@Column(name="remaining_quantity",nullable=false,precision=15,scale=3)private BigDecimal remainingQuantity;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="warehouse_id",nullable=false)private Warehouse warehouse;@Column(name="storage_location")private String storageLocation;@Column(name="batch_number")private String batchNumber;@Column(name="serial_number")private String serialNumber;@Column(name="expiry_date")private LocalDate expiryDate;@Column(length=500)private String remarks;}
